package de.lazytv.pro.live;
import android.net.Uri;import android.view.*;import android.widget.FrameLayout;import androidx.media3.ui.PlayerView;import de.lazytv.pro.catalog.ResolvedStream;import java.util.*;import tv.danmaku.ijk.media.player.IjkMediaPlayer;
/** One persistent fallback surface. Media3 remains primary; native recovery tries LibVLC then IJK. */
final class LiveNativeEngine {
 interface Events {void ready();void buffering(boolean value);void failed(int what,int extra);}
 private final PlayerView frame;private final SurfaceView surface;private org.videolan.libvlc.LibVLC vlc;private org.videolan.libvlc.MediaPlayer vlcPlayer;private IjkMediaPlayer ijk;private boolean released,wantsPlay,usingVlc;private int width,height;private ResolvedStream current;private Events currentEvents;
 LiveNativeEngine(PlayerView frame){this.frame=frame;surface=new SurfaceView(frame.getContext());surface.setClickable(false);surface.setFocusable(false);frame.addView(surface,new FrameLayout.LayoutParams(-1,-1,Gravity.CENTER));surface.getHolder().addCallback(new SurfaceHolder.Callback(){public void surfaceCreated(SurfaceHolder holder){if(!released&&ijk!=null&&!usingVlc)ijk.setDisplay(holder);}public void surfaceChanged(SurfaceHolder holder,int format,int w,int h){resize();}public void surfaceDestroyed(SurfaceHolder holder){if(!released&&ijk!=null&&!usingVlc)ijk.setDisplay(null);}});frame.addOnLayoutChangeListener((v,a,b,c,d,e,f,g,h)->resize());surface.setVisibility(View.GONE);}
 void play(ResolvedStream stream,boolean foreground,Events events)throws Exception {current=stream;currentEvents=events;wantsPlay=foreground;surface.setVisibility(View.VISIBLE);width=height=0;if(de.lazytv.pro.player.PlayerFallbackPolicy.vlcSupportsHeaders(stream.headers))playVlc(stream,events);else playIjk(stream,events);}
 private void playVlc(ResolvedStream stream,Events events)throws Exception {usingVlc=true;releaseIjk();if(vlc==null)vlc=new org.videolan.libvlc.LibVLC(frame.getContext(),new ArrayList<String>());if(vlcPlayer==null)vlcPlayer=new org.videolan.libvlc.MediaPlayer(vlc);else vlcPlayer.stop();vlcPlayer.getVLCVout().detachViews();vlcPlayer.getVLCVout().setVideoView(surface);vlcPlayer.getVLCVout().attachViews();org.videolan.libvlc.Media media=new org.videolan.libvlc.Media(vlc,Uri.parse(stream.url));media.addOption(":network-caching=1500");String ua=stream.headers.get("User-Agent"),ref=stream.headers.get("Referer");if(ua!=null&&!ua.isEmpty())media.addOption(":http-user-agent="+ua);if(ref!=null&&!ref.isEmpty())media.addOption(":http-referrer="+ref);vlcPlayer.setMedia(media);media.release();vlcPlayer.setEventListener(event->{if(released||!usingVlc||stream!=current)return;if(event.type==org.videolan.libvlc.MediaPlayer.Event.Buffering)events.buffering(true);else if(event.type==org.videolan.libvlc.MediaPlayer.Event.Playing){events.buffering(false);events.ready();if(!wantsPlay)vlcPlayer.pause();}else if(event.type==org.videolan.libvlc.MediaPlayer.Event.EncounteredError||event.type==org.videolan.libvlc.MediaPlayer.Event.EndReached){frame.post(()->{if(released||!usingVlc||stream!=current)return;try{playIjk(stream,events);}catch(Exception|LinkageError failed){android.util.Log.e("LazyTV-Engine","Native engine unavailable: "+failed.getClass().getSimpleName());events.failed(0,0);}});}});vlcPlayer.play();}
 private void playIjk(ResolvedStream stream,Events events)throws Exception {usingVlc=false;if(vlcPlayer!=null)vlcPlayer.stop();releaseIjk();ijk=new IjkMediaPlayer();IjkMediaPlayer.native_setLogLevel(IjkMediaPlayer.IJK_LOG_SILENT);ijk.setOption(IjkMediaPlayer.OPT_CATEGORY_PLAYER,"mediacodec",0);ijk.setOption(IjkMediaPlayer.OPT_CATEGORY_FORMAT,"timeout",15000000L);ijk.setOption(IjkMediaPlayer.OPT_CATEGORY_FORMAT,"reconnect",0);StringBuilder headers=new StringBuilder();for(Map.Entry<String,String> header:stream.headers.entrySet())if(header.getKey()!=null&&header.getKey().matches("[A-Za-z0-9-]+")&&header.getValue()!=null&&!header.getValue().contains("\r")&&!header.getValue().contains("\n"))headers.append(header.getKey()).append(": ").append(header.getValue()).append("\r\n");ijk.setOption(IjkMediaPlayer.OPT_CATEGORY_FORMAT,"headers",headers.toString());ijk.setDisplay(surface.getHolder());ijk.setDataSource(stream.url);ijk.setOnPreparedListener(mp->{if(released||usingVlc||stream!=current)return;if(wantsPlay)mp.start();events.buffering(false);events.ready();});ijk.setOnVideoSizeChangedListener((mp,w,h,sarN,sarD)->{width=sarD>0?(int)((long)w*Math.max(1,sarN)/sarD):w;height=h;frame.post(this::resize);});ijk.setOnErrorListener((mp,what,extra)->{events.failed(what,extra);return true;});ijk.setOnCompletionListener(mp->events.failed(0,0));ijk.setOnInfoListener((mp,what,extra)->{if(what==701)events.buffering(true);else if(what==702)events.buffering(false);return false;});ijk.prepareAsync();}
 private void resize(){if(released||width<=0||height<=0||frame.getWidth()<=0||frame.getHeight()<=0)return;float ratio=Math.min((float)frame.getWidth()/width,(float)frame.getHeight()/height);FrameLayout.LayoutParams params=new FrameLayout.LayoutParams(Math.max(1,Math.round(width*ratio)),Math.max(1,Math.round(height*ratio)),Gravity.CENTER);ViewGroup.LayoutParams previous=surface.getLayoutParams();if(previous.width!=params.width||previous.height!=params.height)surface.setLayoutParams(params);}
 void pause(){wantsPlay=false;try{if(usingVlc&&vlcPlayer!=null)vlcPlayer.pause();else if(ijk!=null)ijk.pause();}catch(Exception ignored){}}
 void resume(){wantsPlay=true;try{if(usingVlc&&vlcPlayer!=null)vlcPlayer.play();else if(ijk!=null)ijk.start();}catch(Exception ignored){}}
 void stop(){wantsPlay=false;current=null;try{if(vlcPlayer!=null)vlcPlayer.stop();}catch(Exception ignored){}releaseIjk();surface.setVisibility(View.GONE);}
 boolean playing(){try{return usingVlc?vlcPlayer!=null&&vlcPlayer.isPlaying():ijk!=null&&ijk.isPlaying();}catch(Exception ignored){return false;}}
 private void releaseIjk(){if(ijk!=null){try{ijk.reset();ijk.release();}catch(Exception ignored){}ijk=null;}}
 void release(){released=true;current=null;releaseIjk();if(vlcPlayer!=null){try{vlcPlayer.stop();vlcPlayer.getVLCVout().detachViews();vlcPlayer.release();}catch(Exception ignored){}vlcPlayer=null;}if(vlc!=null){try{vlc.release();}catch(Exception ignored){}vlc=null;}frame.removeView(surface);}
}
